<div class="cms-progress" @if($p['mode'] === 'reading') data-cms-reading-progress @endif><label for="{{ $uid }}">{{ $p['label'] }}</label><progress id="{{ $uid }}" max="{{ $progressMaximum - $progressMinimum }}" value="{{ $progressValue - $progressMinimum }}" aria-valuemin="{{ $progressMinimum }}" aria-valuemax="{{ $progressMaximum }}" aria-valuenow="{{ $progressValue }}">{{ $progressPercent }}%</progress><span><span data-reading-value>{{ $progressValue }}</span> {{ $p['unit'] }}</span></div>
